import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as a,o,af as n}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const b=JSON.parse('{"title":"Yuanbao tutorial","description":"Open Yuanbao on the web or desktop and send the first message.","frontmatter":{"title":"Yuanbao tutorial","description":"Open Yuanbao on the web or desktop and send the first message.","domain":"product","tags":["chat"],"role":"tutorial"},"headers":[],"relativePath":"products/yuanbao/yuanbao.md","filePath":"products/yuanbao/yuanbao.md","lastUpdated":1787107158000}'),r={name:"products/yuanbao/yuanbao.md"};function i(l,e,s,d,c,p){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="yuanbao-tutorial" tabindex="-1">Yuanbao tutorial <a class="header-anchor" href="#yuanbao-tutorial" aria-label="Permalink to &quot;Yuanbao tutorial&quot;">​</a></h1><blockquote><p>Start at <a href="https://yuanbao.tencent.com/" target="_blank" rel="noreferrer">yuanbao.tencent.com</a> or the <a href="https://yuanbao.tencent.com/download" target="_blank" rel="noreferrer">download center</a>. This page only repeats entries and capabilities you can check on official pages.</p></blockquote><h2 id="goals-and-non-goals" tabindex="-1">Goals and non-goals <a class="header-anchor" href="#goals-and-non-goals" aria-label="Permalink to &quot;Goals and non-goals&quot;">​</a></h2><p><strong>Audience:</strong> frontend engineers opening Yuanbao for the first time. The home button says <strong>Log In</strong>; use whatever method the page actually offers.</p><p><strong>You will:</strong> send a first prompt on web or a client, and know the desktop shortcut plus the official capability boundary.</p><p><strong>You will not:</strong> get a WeChat/QQ signup guide, a CodeBuddy install, invented model-switch steps, or a fabricated list of 36 suffixes.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>You can reach <code>yuanbao.tencent.com</code> (some resolvers map it into <code>198.18.0.0/15</code>; change DNS / disable Fake-IP before calling it down).</li><li>OS floors come from two official places — do not merge them: <ul><li>Download center: <strong>macOS 11.3+</strong>, <strong>Windows 10+</strong>.</li><li>App Store: <strong>iOS / iPadOS 15.0</strong> or later.</li></ul></li></ul><h2 id="open-it-in-15-minutes" tabindex="-1">Open it in 15 minutes <a class="header-anchor" href="#open-it-in-15-minutes" aria-label="Permalink to &quot;Open it in 15 minutes&quot;">​</a></h2><h3 id="_1-pick-an-official-door" tabindex="-1">1. Pick an official door <a class="header-anchor" href="#_1-pick-an-official-door" aria-label="Permalink to &quot;1. Pick an official door&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Surface</th><th>How</th><th>Source</th></tr></thead><tbody><tr><td>Web</td><td>Open <a href="https://yuanbao.tencent.com/" target="_blank" rel="noreferrer">yuanbao.tencent.com</a>, click <strong>Log In</strong></td><td>Home</td></tr><tr><td>Web (from the desktop landing page)</td><td><a href="https://yuanbao.tencent.com/evt/dl" target="_blank" rel="noreferrer">evt/dl</a> → <strong>使用网页版</strong></td><td>Desktop page</td></tr><tr><td>iOS</td><td>QR on the download center, or App Store “元宝-腾讯全能AI助手” (id <code>6480446430</code>)</td><td><a href="https://yuanbao.tencent.com/download" target="_blank" rel="noreferrer">download</a>, <a href="https://apps.apple.com/cn/app/%E5%85%83%E5%AE%9D-%E8%85%BE%E8%AE%AF%E5%85%A8%E8%83%BDai%E5%8A%A9%E6%89%8B/id6480446430" target="_blank" rel="noreferrer">App Store</a></td></tr><tr><td>Android</td><td>QR on the download center, or Play package <code>com.tencent.hunyuan.app.chat</code></td><td><a href="https://yuanbao.tencent.com/download" target="_blank" rel="noreferrer">download</a>, <a href="https://play.google.com/store/apps/details?id=com.tencent.hunyuan.app.chat" target="_blank" rel="noreferrer">Play</a></td></tr><tr><td>Windows / macOS</td><td>Download center, or <strong>下载电脑版</strong> on the desktop page; Windows also on <a href="https://pc.qq.com/detail/1/detail_36661.html" target="_blank" rel="noreferrer">Tencent Software Center</a></td><td><a href="https://yuanbao.tencent.com/download" target="_blank" rel="noreferrer">download</a>, <a href="https://yuanbao.tencent.com/evt/dl" target="_blank" rel="noreferrer">evt/dl</a></td></tr></tbody></table><p>The terms also name a <strong>mini program</strong> and a <strong>browser plugin</strong> (<a href="https://rule.tencent.com/rule/202403110001" target="_blank" rel="noreferrer">user agreement</a>). No standalone official install page for either was found on 2026-08-19. This tutorial does not invent steps.</p><p>The old URL <code>https://hunyuan.tencent.com/bot/chat</code> already canonicalizes to the Yuanbao site. Do not bookmark it as “Hunyuan chat”.</p><h3 id="_2-send-the-first-prompt" tabindex="-1">2. Send the first prompt <a class="header-anchor" href="#_2-send-the-first-prompt" aria-label="Permalink to &quot;2. Send the first prompt&quot;">​</a></h3><p>Logged-out home copy: “Hi, 我是元宝” and “聊天、写作、搜索都在行，助你灵感无限”. After login, type in the box or drag a file (home: <strong>Drag the file here to upload</strong>).</p><p>The footer says AI-generated content is for reference only. Treat that as a product statement.</p><h3 id="_3-desktop-select-to-ask-and-the-mini-window" tabindex="-1">3. Desktop: select-to-ask and the mini window <a class="header-anchor" href="#_3-desktop-select-to-ask-and-the-mini-window" aria-label="Permalink to &quot;3. Desktop: select-to-ask and the mini window&quot;">​</a></h3><p>Install the desktop app only if you need an OS-level overlay. The official desktop page (<a href="https://yuanbao.tencent.com/evt/dl" target="_blank" rel="noreferrer">evt/dl</a>) says:</p><table tabindex="0"><thead><tr><th>Action</th><th>Official wording</th></tr></thead><tbody><tr><td>Mini chat</td><td>Option+Space (mac) or Alt+Space (window) opens the mini window</td></tr><tr><td>Select-to-ask</td><td>Select-to-search and translate; ask Yuanbao anything</td></tr><tr><td>Vision</td><td>Screenshot upload, then search</td></tr><tr><td>Temporary chat</td><td>Temporary chats do not appear in history</td></tr><tr><td>Save</td><td>One-tap save for a good answer</td></tr></tbody></table><p>Tencent Software Center also lists global select-to-ask (translate / search / read aloud), grouped custom instructions, and import/export with Tencent Docs.</p><h2 id="official-capabilities-by-source" tabindex="-1">Official capabilities (by source) <a class="header-anchor" href="#official-capabilities-by-source" aria-label="Permalink to &quot;Official capabilities (by source)&quot;">​</a></h2><h3 id="home" tabindex="-1">Home <a class="header-anchor" href="#home" aria-label="Permalink to &quot;Home&quot;">​</a></h3><p><a href="https://yuanbao.tencent.com/" target="_blank" rel="noreferrer">yuanbao.tencent.com</a> describes an all-in-one assistant on Hunyuan Hy3, with stronger file handling, writing styles, companion chat, search, image understanding, image edit, and homework Q&amp;A.</p><p>Visible nav also includes <strong>Search</strong>, <strong>All Collections</strong>, and <strong>Download Center</strong>. There is no separate official doc for Collections / Group, so this page does not invent rules.</p><h3 id="desktop-landing-page" tabindex="-1">Desktop landing page <a class="header-anchor" href="#desktop-landing-page" aria-label="Permalink to &quot;Desktop landing page&quot;">​</a></h3><p><a href="https://yuanbao.tencent.com/evt/dl" target="_blank" rel="noreferrer">evt/dl</a> columns: <strong>混元 Hy3</strong>, <strong>AI 写作</strong>, <strong>AI 编程</strong>, <strong>AI 识图</strong>, <strong>AI 划词</strong>.</p><p>The only official coding sentences:</p><ul><li>AI coding without a local deploy, instant check</li><li>Python and C++ run in the product, no deploy required</li></ul><p>That is <strong>code in the thread</strong>, not clone-a-repo / open-a-PR / MCP. Repo-level coding is <a href="https://www.codebuddy.cn/" target="_blank" rel="noreferrer">CodeBuddy</a> (site issue #78; no tutorial here).</p><p>Files: “36 kinds” including code, logs, and technical docs. <strong>No</strong> official suffix table.</p><h3 id="store-long-description" tabindex="-1">Store long description <a class="header-anchor" href="#store-long-description" aria-label="Permalink to &quot;Store long description&quot;">​</a></h3><p>App Store and Play feature lists matched on 2026-08-19: image edit, homework solver, <strong>Yuanbao Pai (public beta, including raising lobsters)</strong>, unlimited-time voice-note transcription/translation, fast reports / copy / code, AI tutor, image-to-video, voice calls, snap-to-search, snap-to-translate, QQ Music, image generation, links to WeChat / Tencent Docs / Tencent News / Weixin Reading, official-account and Channels sources, 36 file types, and trending search.</p><p>“Links with WeChat” is one store bullet. It is <strong>not</strong> a WeChat integration tutorial.</p><p>Treat Yuanbao Pai as an in-app public beta, not its own handbook.</p><h2 id="do-not-pick-a-winner-on-model-copy" tabindex="-1">Do not pick a winner on model copy <a class="header-anchor" href="#do-not-pick-a-winner-on-model-copy" aria-label="Permalink to &quot;Do not pick a winner on model copy&quot;">​</a></h2><p>Three official wordings existed on 2026-08-19:</p><table tabindex="0"><thead><tr><th>Source</th><th>Wording</th></tr></thead><tbody><tr><td>Home / desktop page</td><td>Hunyuan <strong>Hy3</strong></td></tr><tr><td>App Store release notes</td><td>2.66–2.67 “Hy3 preview”; 2.76–2.78 “Hy3 generally available”</td></tr><tr><td>Play “About this app”</td><td>Hunyuan T1 and DeepSeek R1 dual reasoning models</td></tr></tbody></table><p>Trust the names in your client. Do not write “DeepSeek is the default” or “T1 has been removed”. Internals: <a href="/tech/fundamentals/LLM.html">Learn LLM</a>.</p><h2 id="legal-and-support" tabindex="-1">Legal and support <a class="header-anchor" href="#legal-and-support" aria-label="Permalink to &quot;Legal and support&quot;">​</a></h2><ul><li><a href="https://rule.tencent.com/rule/202403110001" target="_blank" rel="noreferrer">Yuanbao user agreement</a></li><li><a href="https://privacy.qq.com/document/preview/eb9be56572ab4886b6ca124e72abf413" target="_blank" rel="noreferrer">Yuanbao privacy policy</a></li></ul><p>The agreement names web, PC client, mini program, and browser plugin. The rule center needs JavaScript. This page does not paraphrase grant language.</p><p>Play support email: <code>yuanbao@tencent.com</code>.</p><h2 id="pitfalls" tabindex="-1">Pitfalls <a class="header-anchor" href="#pitfalls" aria-label="Permalink to &quot;Pitfalls&quot;">​</a></h2><ul><li>Treating Yuanbao as Claude Code / Cursor. There is no official Yuanbao CLI or IDE plugin page.</li><li>Copying 2025 “four-model” blog matrices. Home now says Hy3; Play still mentions T1 + R1.</li><li>Inventing the 36 suffixes.</li><li>Writing mini-program / plugin install steps with no official install URL.</li><li>Saving <code>hunyuan.tencent.com/bot/chat</code> as a Hunyuan chat product.</li></ul><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="./yuanbao-cheatsheet.html">Cheatsheet</a></li><li><a href="./yuanbao-glossary.html">Glossary</a></li><li><a href="./">Learning map</a></li></ul>',46)])])}const m=t(r,[["render",i]]);export{b as __pageData,m as default};
